"""Find the stretches of opening hours nobody is covering."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def check_inside(worked: List[Span], opening: Span):
    """Raise ValueError if any worked span leaves opening hours."""
    for span in worked:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(
                f"{format_span(span)} is outside opening hours "
                f"{format_span(opening)}"
            )


def uncovered(worked: List[Span], opening: Span) -> List[Span]:
    """The spans of opening hours that no worked span touches."""
    found = []
    cursor = opening.start
    for span in merge_spans(worked):
        if span.start > cursor:
            found.append(Span(cursor, span.start))
        cursor = span.end
    if cursor < opening.end:
        found.append(Span(cursor, opening.end))
    return found


def format_gap(span: Span) -> str:
    return f"gap {format_span(span)} ({span.minutes} min)"


def find_gaps(worked: Iterable[Span], opening: Span) -> List[str]:
    """One label per uncovered stretch, such as
    gap 12:00-13:00 (60 min). Raises ValueError when a worked
    span falls outside opening hours."""
    worked = list(worked)
    check_inside(worked, opening)
    return [format_gap(item) for item in uncovered(worked, opening)]
EOF
