from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def check_inside(worked: List[Span], opening: Span):
    """Raise ValueError if a span leaves opening hours."""
    for span in worked:
        if span.start < opening.start:
            raise ValueError(outside_text(span, opening))
        if span.end > opening.end:
            raise ValueError(outside_text(span, opening))


def outside_text(span: Span, opening: Span) -> str:
    return (f"{format_span(span)} is outside "
            f"opening hours {format_span(opening)}")


def between(first: int, last: int) -> List[Span]:
    return [Span(first, last)] if first < last else []


def uncovered(worked: List[Span], opening: Span):
    """Parts of opening hours nobody covers."""
    found = []
    cursor = opening.start
    for span in merge_spans(worked):
        found += between(cursor, span.start)
        cursor = span.end
    return found + between(cursor, opening.end)


def format_gap(span: Span) -> str:
    return f"gap {format_span(span)} ({span.minutes} min)"


def find_gaps(worked: Iterable[Span], opening: Span):
    """One label per uncovered stretch, such as
    "gap 12:00-13:00 (60 min)". Raises ValueError when
    a worked span is outside opening hours."""
    worked = list(worked)
    check_inside(worked, opening)
    found = uncovered(worked, opening)
    return [format_gap(gap) for gap in found]

